    while (swapCount < N - 1) {
        for (int i = 0; i < N - 1; i++) {
            if (seats[i] != seats[i + 1]) {
                int temp = seats[i];
                seats[i] = seats[i + 1];
                seats[i + 1] = temp;
                swapCount++;
            }
        }
        timeNeeded++;
    }
    return timeNeeded;
}
