public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // check if start and end are within the bounds of the maze
    if (start[0] < 0 || start[1] < 0 || end[0] < 0 || end[1] < 0 || start[0] >= n || start[1] >= n || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // create a 2D array to represent the maze
    int[][] maze = new int[n][n];
    for (int[] path : paths) {
        maze[path[0]][path[1]] = 1;
        maze[path[1]][path[0]] = 1;
    }

    // perform BFS to find the shortest path between start and end
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int i = 0; i < n; i++) {
            int nextX = current[0] + i;
            int nextY = current[1] + i;
            if (nextX < 0 || nextX >= n || nextY < 0 || nextY >= n || maze[nextX][nextY] == 0) {
                continue;
            }
            queue.add(new int[] { nextX, nextY });
        }
    }

    return "cannot be travelled";
}
