public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue to perform BFS traversal
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start);
    visited[start[0] * n + start[1]] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.remove();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Add all adjacent n-tersections to the queue that have not been visited yet
        for (int[] path : paths) {
            int x = current[0] + path[0];
            int y = current[1] + path[1];
            int z = x * n + y;

            if (x >= 0 && x < n && y >= 0 && y < n && !visited[z]) {
                queue.add(new int[] {x, y});
                visited[z] = true;
            }
        }
    }

    // If no path was found, return "cannot be travelled"
    return "cannot be travelled";
}
