        int[] current = queue.poll();
        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // Iterate through all adjacent n-tersections
        for (int[] adjacent : getAdjacent(current, n, paths)) {
            // If the adjacent n-tersection is not visited, add it to the queue and visited set
            if (!visited.contains(adjacent)) {
                queue.add(adjacent);
                visited.add(adjacent);
            }
        }
