// Helper method to get all adjacent n-tersections
private static int[][] getAdjacent(int[] ntersection, int n, int[][] paths) {
    // Initialize a list to store the adjacent n-tersections
    List<int[]> adjacent = new ArrayList<>();
    // Iterate through all paths
    for (int[] path : paths) {
        // If the current path contains the n-tersection, add its adjacent n-tersections to the list
        if (pathContains(ntersection, path, n)) {
            adjacent.add(getOther(path, ntersection, n));
        }
    }
    // Return the list of adjacent n-tersections
    return adjacent.toArray(new int[adjacent.size()][n]);
}

// Helper method to check if a path contains a given n-tersection
private static boolean pathContains(int[] ntersection, int[] path, int n) {
    for (int i = 0; i < n; i++) {
        if (path[i] == ntersection[i]) {
            return true;
        }
    }
    return false;
}

// Helper method to get the other n-tersection in a path that contains a given n-tersection
private static int[] getOther(int[] path, int[] ntersection, int n) {
    int[] other = new int[n];
    for (int i = 0; i < n; i++) {
        if (path[i] != ntersection[i]) {
            other[i] = path[i];
        }
    }
    return other;
}
