    // Calculate the mean of the entire array
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Calculate the trimmed mean
    double trimmedMean = 0;
    int trimmedCount = (int) (0.95 * arr.length);
    for (int i = 0; i < arr.length; i++) {
        if (i < trimmedCount / 2 || i >= arr.length - trimmedCount / 2) {
