public int[] bfs(Graph graph, int start) {
    int n = graph.getNumVertices();
    int[] dist = new int[n];
    LinkedList<Integer> queue = new LinkedList<>();

    // Initialize all distances to -1
    Arrays.fill(dist, -1);
    dist[start] = 0;
    queue.offer(start);

    // BFS traversal
    while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : graph.getNeighbors(u)) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue.offer(v);
            }
        }
    }

    return dist;
}

