    public static void main(String[] args) {
        System.out.println(hasAllCodes("00110110", 2)); // true
        System.out.println(hasAllCodes("00110110", 3)); // false
        System.out.println(hasAllCodes("10011", 3)); // false
        System.out.println(hasAllCodes("10011", 4)); // true
        System.out.println(hasAllCodes("10011", 5)); // true
    }

    public static boolean hasAllCodes(String s, int k) {
        int n = s.length();
        if (n < k || k <= 0) {
            return false;
        }
        int[] counts = new int[1 << k];
        Arrays.fill(counts, 0);
        int code = 0;
        for (int i = 0; i < n; i++) {
            code = (code << 1) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                counts[code]++;
                code &= ~(1 << (k - 1));
            }
        }
        for (int i = 0; i < 1 << k; i++) {
            if (counts[i] == 0) {
                return false;
            }
        }
        return true;
    }
}

