public static int[] collectRainwater(int[] heights, int[] collectors) {
    int[] water = new int[collectors.length];
    for (int i = 0; i < collectors.length; i++) {
        int left = 0;
        for (int j = 0; j < collectors[i]; j++) {
            left = Math.max(left, heights[j]);
        }
        int right = 0;
        for (int j = collectors[i] + 1; j < heights.length; j++) {
            right = Math.max(right, heights[j]);
        }
        water[i] = Math.min(left, right) - heights[collectors[i]];
    }
    return water;
}
