        for (int j = 0; j < n; j++) {
            // Check if the current element is 1
            if (mat[i][j] == 1) {
                // Initialize the current line length
                int currentLineLength = 1;

                // Check if the element is on the edge of the array
                if (i == 0 || j == 0 || i == m - 1 || j == n - 1) {
                    // If the element is on the edge, only consider one direction
                    currentLineLength = getLongestContinuousLineLength(mat, i, j);
                } else {
                    // If the element is not on the edge, consider all directions
                    currentLineLength = Math.max(currentLineLength, getLongestContinuousLineLength(mat, i, j));
                    currentLineLength = Math.max(currentLineLength, getLongestContinuousLineLength(mat, i, j + 1));
                    currentLineLength = Math.max(currentLineLength, getLongestContinuousLineLength(mat, i + 1, j));
                    currentLineLength = Math.max(currentLineLength, getLongestContinuousLineLength(mat, i + 1, j + 1));
                }

                // Update the longest line length
                longestLine = Math.max(longestLine, currentLineLength);
            }
        }
