    if (i >= 0 && i < m && j >= 0 && j < n && mat[i][j] == 1) {
        length++;
        length += getLongestContinuousLineLength(mat, i + 1, j);
        length += getLongestContinuousLineLength(mat, i - 1, j);
        length += getLongestContinuousLineLength(mat, i, j + 1);
        length += getLongestContinuousLineLength(mat, i, j - 1);
    }

    return length;
}

