    String strNum = Integer.toString(num);
    int centerIndex = strNum.length() / 2;
    int i = centerIndex - 1;
    int j = centerIndex + 1;
    while (i >= 0 && j < strNum.length()) {
        if (strNum.charAt(i) != strNum.charAt(j)) {
            return false;
        }
        i--;
        j++;
    }
    return true;
}

