  List<String> result = new ArrayList<>();
  char[] arr = new char[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (char) ('0' + i);
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (arr[j] == arr[i] && arr[j] != '0') {
        result.add(new String(arr));
        break;
      }
    }
    rotate(arr);
  }
  return result;
}

private static void rotate(char[] arr) {
  int n = arr.length;
  char temp = arr[0];
  for (int i = 1; i < n; i++) {
    arr[i - 1] = arr[i];
  }
  arr[n - 1] = temp;
}

