public class UglyNumberFinder {

    public static int findNthUglyNumber(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("The input must be a positive integer.");
        }

        // Initialize a priority queue to store the multiples of 2, 3, and 5
        PriorityQueue<Long> queue = new PriorityQueue<>();
        Map<Long, Integer> countMap = new HashMap<>();
        queue.offer(1L);
        countMap.put(1L, 0);

        for (int i = 0; i < n; i++) {
            Long currentNum = queue.poll();
            int currentCount = countMap.get(currentNum);
            if (currentCount == 0) {
                countMap.put(currentNum, 1);
            } else {
                countMap.put(currentNum, currentCount + 1);
            }

            // Add the multiples of currentNum to the queue
            if (currentNum % 2 == 0 && countMap.get(currentNum / 2) < 1) {
                queue.offer(currentNum / 2);
                countMap.put(currentNum / 2, 0);
            }
            if (currentNum % 3 == 0 && countMap.get(currentNum / 3) < 1) {
                queue.offer(currentNum / 3);
                countMap.put(currentNum / 3, 0);
            }
            if (countMap.get(currentNum % 5) < 1) {
                queue.offer(currentNum % 5);
                countMap.put(currentNum % 5, 0);
            }
        }

        return queue.peek().intValue();
    }
}

