    if (n <= 0) {
        return 0;
    }
    int min = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        min = Math.min(min, minPerfectSquareSum(n - i * i) + 1);
    }
    return min;
}
